insert into catalog.domain (code, name, description, icon, tone, sort, updated_at, updated_by) values
  ('TM', '{"ar": "الوقت والإجازات", "en": "Time & leave"}'::jsonb, '{"ar": "دوام الموظف وإجازاته وأرصدته."}'::jsonb, 'leave', 'g-green', 10, now(), 'system:catalogue-1.0'),
  ('MD', '{"ar": "بياناتي ومستنداتي", "en": "My data & documents"}'::jsonb, '{"ar": "ما يملكه الموظف من بيانات ووثائق، وتحديثها من مكان واحد."}'::jsonb, 'idcard', 'g-gold', 20, now(), 'system:catalogue-1.0'),
  ('DC', '{"ar": "الخطابات والوثائق الرسمية", "en": "Letters & official documents"}'::jsonb, '{"ar": "ما تُصدره الأمانة العامة للموظف من خطابات وشهادات وبطاقات."}'::jsonb, 'letter', 'g-bronze', 30, now(), 'system:catalogue-1.0'),
  ('HA', '{"ar": "الحركات الوظيفية والهيكل التنظيمي", "en": "HR actions & organisation"}'::jsonb, '{"ar": "يبدأها المدير أو الإدارة أو الموارد البشرية، والموظف طرف فيها."}'::jsonb, 'team', 'g-sage', 40, now(), 'system:catalogue-1.0'),
  ('FN', '{"ar": "المعاملات المالية للموظف", "en": "Employee finance"}'::jsonb, '{"ar": "كل ما ينتهي بمبلغ يُحجز أو يُصرف أو يُسوّى."}'::jsonb, 'wallet', 'g-teal', 50, now(), 'system:catalogue-1.0'),
  ('MI', '{"ar": "التأمين الطبي", "en": "Medical insurance"}'::jsonb, '{"ar": "الموظف ومرافقوه لدى شركة التأمين."}'::jsonb, 'shield', null, 60, now(), 'system:catalogue-1.0'),
  ('GR', '{"ar": "الإقامة والتأشيرات والعلاقات الحكومية", "en": "Residency, visas & government relations"}'::jsonb, '{"ar": "ما يمر عبر وزارة الخارجية والجهات الحكومية."}'::jsonb, 'passport', null, 70, now(), 'system:catalogue-1.0'),
  ('TD', '{"ar": "التدريب والتطوير والأداء", "en": "Training, development & performance"}'::jsonb, '{"ar": "الدورات والابتعاث وتقييم الأداء."}'::jsonb, 'sparkle', null, 80, now(), 'system:catalogue-1.0'),
  ('LC', '{"ar": "رحلات دورة الحياة الوظيفية", "en": "Lifecycle journeys"}'::jsonb, '{"ar": "مسار واحد يجمع خدمات عدة: الالتحاق، وانتهاء الخدمة، والانتقال."}'::jsonb, 'person', null, 90, now(), 'system:catalogue-1.0'),
  ('AS', '{"ar": "الاحتياج والعهد والأصول", "en": "Needs, custody & assets"}'::jsonb, '{"ar": "ما يحتاجه الموظف أو الإدارة من مواد وأجهزة، وما في عهدتهم."}'::jsonb, 'box', 'g-bronze', 100, now(), 'system:catalogue-1.0'),
  ('PR', '{"ar": "المشتريات والعقود (للإدارات)", "en": "Procurement & contracts (departments)"}'::jsonb, '{"ar": "دور الإدارة الطالبة واللجان في دورة الشراء والمنافسات."}'::jsonb, 'grid', 'g-gold', 110, now(), 'system:catalogue-1.0'),
  ('BG', '{"ar": "الموازنة (للإدارات)", "en": "Budget (departments)"}'::jsonb, '{"ar": "خطة الإدارة السنوية ومناقلاتها."}'::jsonb, 'balance', null, 120, now(), 'system:catalogue-1.0'),
  ('GV', '{"ar": "الاجتماعات واللجان والمهام والمشاريع", "en": "Meetings, committees, tasks & projects"}'::jsonb, '{"ar": "عمل الحوكمة اليومي الذي يولّد مهام وقرارات."}'::jsonb, 'calendar', 'g-green', 130, now(), 'system:catalogue-1.0'),
  ('SY', '{"ar": "تشغيل المنظومة (للإدارات)", "en": "System operations (departments)"}'::jsonb, '{"ar": "طلبات الإدارات على المنظومة نفسها: بيانات رئيسية وتغييرات."}'::jsonb, 'gear', null, 140, now(), 'system:catalogue-1.0'),
  ('EV', '{"ar": "مشاركة الموظف", "en": "Employee voice"}'::jsonb, '{"ar": "صوت الموظف: تظلم، ومقترح، وامتياز."}'::jsonb, 'bell', null, 150, now(), 'system:catalogue-1.0'),
  ('WP', '{"ar": "خدمات مكان العمل والدعم", "en": "Workplace & support"}'::jsonb, '{"ar": "خدمات لا تنتهي في S/4HANA وتحتاج محرك خدمات مستضافاً في المملكة."}'::jsonb, 'home', null, 160, now(), 'system:catalogue-1.0');
insert into catalog.service (id, domain_code, name, scope, requesters, target, frequency, status, merged_into, sort, updated_at, updated_by) values
  ('TM-01', 'TM', '{"ar": "طلب إجازة", "en": "Leave request"}'::jsonb, '{"ar": "جميع أنواع الإجازات وفق سجل الأنواع المعتمد، مع عرض الرصيد لحظة الطلب، والموافقات، وتعديل الإجازة المعتمدة أو إلغاؤها بإعادة احتساب الرصيد والأثر المالي."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: الوقت (PT) وأثرها في الرواتب"}'::jsonb, 'high', 'available', null, 10, now(), 'system:catalogue-1.0'),
  ('TM-02', 'TM', '{"ar": "طلب ترحيل رصيد الإجازة", "en": "Carry over leave balance"}'::jsonb, '{"ar": "طلب ترحيل الرصيد المتبقي وفق الضوابط، بموافقة صاحب الصلاحية، وانعكاسه على الرصيد."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: أرصدة الإجازات (PT)"}'::jsonb, 'seasonal', 'wave2', null, 20, now(), 'system:catalogue-1.0'),
  ('TM-03', 'TM', '{"ar": "الاستئذان", "en": "Short permission"}'::jsonb, '{"ar": "إذن خروج أو تأخر لساعات محددة بموافقة المدير المباشر، واحتسابه آلياً في سجل الحضور."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: الوقت (PT)"}'::jsonb, 'high', 'later', null, 30, now(), 'system:catalogue-1.0'),
  ('TM-04', 'TM', '{"ar": "تصحيح سجل الحضور", "en": "Attendance correction"}'::jsonb, '{"ar": "طلب تصحيح بصمة مفقودة أو خاطئة بمبرر ومرفق وموافقة المدير، وانعكاسه على السجل من التاريخ الصحيح."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: أحداث الوقت (PT) بالتكامل مع أجهزة البصمة"}'::jsonb, 'high', 'wave2', null, 40, now(), 'system:catalogue-1.0'),
  ('TM-05', 'TM', '{"ar": "العمل عن بعد", "en": "Remote work"}'::jsonb, '{"ar": "طلب أيام عمل عن بعد ضمن الحصة المعتمدة والضوابط، وربطه بالحضور."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: الوقت (PT)"}'::jsonb, 'medium', 'wave2', null, 50, now(), 'system:catalogue-1.0'),
  ('TM-06', 'TM', '{"ar": "تعديل جدول العمل أو تبديل المناوبة", "en": "Work schedule or shift swap"}'::jsonb, '{"ar": "تعديل جدول عمل الموظف (ومنه جداول الدراسة والأمومة) أو تبديل مناوبة مع زميل بموافقة صاحب الصلاحية."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: جداول العمل (PT)"}'::jsonb, 'low', 'wave3', null, 60, now(), 'system:catalogue-1.0'),
  ('TM-07', 'TM', '{"ar": "العمل الإضافي", "en": "Overtime"}'::jsonb, '{"ar": "طلب الساعات مسبقاً، ثم إثبات الأداء من سجل الحضور، والاعتماد، والارتباط المالي، والصرف من خلال الرواتب."}'::jsonb, '{"ar": "موظف، مدير"}'::jsonb, '{"ar": "الوقت (PT) والرواتب (PY) والاعتمادات (FM)"}'::jsonb, 'medium', 'wave2', null, 70, now(), 'system:catalogue-1.0'),
  ('MD-01', 'MD', '{"ar": "تحديث بياناتي الشخصية", "en": "Update my personal data"}'::jsonb, '{"ar": "بيانات الاتصال والعنوان والحالة الاجتماعية وأرقام البطاقات، بإرفاق الإثبات عند الحاجة وموافقة صاحب الصلاحية، وتحديث النظام المرجعي وسجل التغيير."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: البيانات الرئيسية للموظف (PA)"}'::jsonb, 'high', 'available', null, 10, now(), 'system:catalogue-1.0'),
  ('MD-02', 'MD', '{"ar": "تغيير الحساب البنكي", "en": "Change salary account"}'::jsonb, '{"ar": "تغيير حساب صرف الراتب بتحقق إضافي (مستند بنكي وتأكيد ثانٍ)، وبيان واضح لأثره على دورة الراتب القادمة."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: بيانات البنك (PA) → الرواتب (PY)"}'::jsonb, 'low', 'available', null, 20, now(), 'system:catalogue-1.0'),
  ('MD-03', 'MD', '{"ar": "أفراد الأسرة والمرافقون"}'::jsonb, '{"ar": "إضافة مرافق أو تحديث بياناته بالمرفقات الثبوتية بوصفها أساس الاستحقاقات (التذاكر، التعليم، التأمين، التأشيرات)؛ ويشمل مسار المولود الجديد في طلب واحد."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: أفراد الأسرة (PA) + التأمين"}'::jsonb, 'medium', 'wave2', null, 30, now(), 'system:catalogue-1.0'),
  ('MD-04', 'MD', '{"ar": "مؤهلاتي وشهاداتي"}'::jsonb, '{"ar": "تسجيل مؤهل أو شهادة جديدة بالإثبات لاعتمادها في الملف، وعرض الشهادات التدريبية المسجلة."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: التعليم والمؤهلات (PA)"}'::jsonb, 'low', 'wave3', null, 40, now(), 'system:catalogue-1.0'),
  ('MD-05', 'MD', '{"ar": "تحديث مستند (جواز، هوية، إقامة، رخصة)", "en": "Update a document (passport, ID, residency, licence)"}'::jsonb, '{"ar": "تحديث مستند من الملف الوثائقي بصورة المستند الجديد وتواريخه، بمراجعة المختص وتحديث النظام المرجعي، انطلاقاً من تنبيه الانتهاء نفسه."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية: مستندات الهوية (PA) + مستودع المحتوى"}'::jsonb, 'high', 'available', null, 50, now(), 'system:catalogue-1.0'),
  ('MD-06', 'MD', '{"ar": "خصوصيتي وحقوقي على بياناتي"}'::jsonb, '{"ar": "الاطلاع على البيانات المحفوظة وطلب تصحيحها وفق ضوابط حماية البيانات، والتحكم بمن يرى الصورة الشخصية بقيمة افتراضية هي الأضيق."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "البوابة + الموارد البشرية (PA)"}'::jsonb, 'low', 'wave3', null, 60, now(), 'system:catalogue-1.0'),
  ('DC-01', 'DC', '{"ar": "خطاب تعريف", "en": "Employment letter"}'::jsonb, '{"ar": "خطاب تعريف بالراتب أو بدونه موجه إلى جهة محددة، يصدر إلكترونياً برمز تحقق خلال دقائق دون تدخل يدوي عند اكتمال البيانات."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "قراءة من الموارد البشرية والرواتب؛ الإصدار من البوابة"}'::jsonb, 'high', 'available', null, 10, now(), 'system:catalogue-1.0'),
  ('DC-02', 'DC', '{"ar": "شهادة خبرة أو شهادة خدمة"}'::jsonb, '{"ar": "شهادة بصيغة معتمدة للموظف الحالي أو السابق، برمز تحقق، وموافقة صاحب الصلاحية عند الحاجة."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية (PA)؛ الإصدار من البوابة"}'::jsonb, 'low', 'wave2', null, 20, now(), 'system:catalogue-1.0'),
  ('DC-03', 'DC', '{"ar": "خطاب لجهة خارجية (سفارة، بنك، جهة تعليمية)"}'::jsonb, '{"ar": "خطابات بصيغ معتمدة وباللغتين عند الحاجة، بموافقة صاحب الصلاحية، وإرسالها للجهة المستفيدة برمز تحقق."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية (PA)؛ الإصدار من البوابة"}'::jsonb, 'medium', 'wave2', null, 30, now(), 'system:catalogue-1.0'),
  ('DC-04', 'DC', '{"ar": "بطاقة الهوية الوظيفية وبطاقة العمل"}'::jsonb, '{"ar": "إصدار أو بدل فاقد باعتماد الصورة والبيانات، وطباعة البطاقة وتسليمها."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الموارد البشرية (PA) + طباعة البطاقات (خارج النظام حالياً)"}'::jsonb, 'low', 'wave2', null, 40, now(), 'system:catalogue-1.0'),
  ('HA-01', 'HA', '{"ar": "نقل موظف"}'::jsonb, '{"ar": "طلب النقل بين الوحدات التنظيمية باعتماد الطرفين وصاحب الصلاحية، وتحديث آلي للبيانات والهيكل والصلاحيات، وإشعار الموظف."}'::jsonb, '{"ar": "مدير، إدارة"}'::jsonb, '{"ar": "الموارد البشرية: الإجراءات (PA) والهيكل (OM)"}'::jsonb, 'medium', 'wave2', null, 10, now(), 'system:catalogue-1.0'),
  ('HA-02', 'HA', '{"ar": "تكليف"}'::jsonb, '{"ar": "تكليف الموظف بمهام أو منصب بمدة محددة وسلسلة موافقات، وتحديث البيانات وأي أثر في الوقت أو الاستحقاق."}'::jsonb, '{"ar": "مدير، إدارة"}'::jsonb, '{"ar": "الموارد البشرية: الإجراءات (PA)"}'::jsonb, 'medium', 'wave2', null, 20, now(), 'system:catalogue-1.0'),
  ('HA-03', 'HA', '{"ar": "ترقية"}'::jsonb, '{"ar": "قرار الترقية بسلسلة موافقات وتحديث الدرجة والمسمى، واحتساب فروقات الترقية آلياً في الرواتب."}'::jsonb, '{"ar": "الموارد البشرية، مدير"}'::jsonb, '{"ar": "الموارد البشرية: الإجراءات (PA) → الرواتب (PY)"}'::jsonb, 'seasonal', 'wave2', null, 30, now(), 'system:catalogue-1.0'),
  ('HA-04', 'HA', '{"ar": "تثبيت بعد فترة التجربة"}'::jsonb, '{"ar": "تقييم فترة التجربة وقرار التثبيت، يبدأ آلياً قبل انتهاء الفترة ويُغلق بتحديث السجل."}'::jsonb, '{"ar": "مدير"}'::jsonb, '{"ar": "الموارد البشرية: الإجراءات (PA)"}'::jsonb, 'low', 'wave2', null, 40, now(), 'system:catalogue-1.0'),
  ('HA-05', 'HA', '{"ar": "تجديد العقد أو تمديد الخدمة"}'::jsonb, '{"ar": "مسار اعتماد التجديد أو الإنهاء قبل انتهاء العقد، يبدأ آلياً من تنبيه انتهاء العقد ويُحدِّث السجل."}'::jsonb, '{"ar": "الموارد البشرية، مدير"}'::jsonb, '{"ar": "الموارد البشرية: الإجراءات (PA)"}'::jsonb, 'seasonal', 'wave2', null, 50, now(), 'system:catalogue-1.0'),
  ('HA-06', 'HA', '{"ar": "معارو الأمانة العامة"}'::jsonb, '{"ar": "تسجيل المعار ومتابعة مدة الإعارة وانتهائها وتجديدها."}'::jsonb, '{"ar": "الموارد البشرية"}'::jsonb, '{"ar": "الموارد البشرية: الإجراءات (PA)"}'::jsonb, 'low', 'wave3', null, 60, now(), 'system:catalogue-1.0'),
  ('HA-07', 'HA', '{"ar": "استحداث أو تعديل وظيفة أو وحدة تنظيمية"}'::jsonb, '{"ar": "طلب من الإدارة باعتماد أصحاب الصلاحية وانعكاسه على الهيكل: الوحدات، والمناصب، والوظائف."}'::jsonb, '{"ar": "إدارة"}'::jsonb, '{"ar": "الموارد البشرية: الهيكل التنظيمي (OM)"}'::jsonb, 'low', 'wave3', null, 70, now(), 'system:catalogue-1.0'),
  ('HA-08', 'HA', '{"ar": "التقدم لوظيفة داخلية"}'::jsonb, '{"ar": "الإعلان الداخلي عن الشواغر، وتقديم الموظف عليها، ومتابعة حالة الترشيح حتى القرار."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "محرك الاستقطاب (يُقرَّر: نظام التوظيف الحالي أم بديل)"}'::jsonb, 'seasonal', 'wave3', null, 80, now(), 'system:catalogue-1.0'),
  ('HA-09', 'HA', '{"ar": "تسجيل شخص خارجي (ضابط ارتباط، متدرب تعاوني، موظف شركة)"}'::jsonb, '{"ar": "طلب من الإدارة لتسجيل شخص خارجي بصلاحيات ومدة محددة، وإصدار بطاقة وحساب عند الحاجة، وإنهاء آلي عند انتهاء المدة."}'::jsonb, '{"ar": "إدارة"}'::jsonb, '{"ar": "الموارد البشرية: الأشخاص الخارجيون (PA) + الحسابات التقنية"}'::jsonb, 'medium', 'wave2', null, 90, now(), 'system:catalogue-1.0'),
  ('FN-01', 'FN', '{"ar": "الانتداب ومهمة العمل", "en": "Business trip & assignment"}'::jsonb, '{"ar": "طلب الانتداب (مهمة عمل أو تدريب) بحجز الاعتماد قبل الاعتماد النهائي، والتذاكر ومقدم الانتداب، وتسجيل الحضور لفترة المهمة، والتسوية بعد العودة من الارتباط نفسه."}'::jsonb, '{"ar": "موظف، مدير"}'::jsonb, '{"ar": "الاعتمادات (FM) والرواتب (PY) والوقت (PT)؛ نطاق ترخيص إدارة السفر (FI-TV) بند مفتوح"}'::jsonb, 'high', 'available', null, 10, now(), 'system:catalogue-1.0'),
  ('FN-02', 'FN', '{"ar": "السلفة وتسويتها"}'::jsonb, '{"ar": "طلب السلفة وفحص الاستحقاق والاعتماد المالي والصرف، ثم تقديم المصروفات وتسوية الفائض أو الفرق وإقفالها، ومنع سلفة جديدة عند تجاوز الضوابط."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "المالية (FI/FM) والرواتب (PY) للاستقطاع"}'::jsonb, 'medium', 'wave2', null, 20, now(), 'system:catalogue-1.0'),
  ('FN-03', 'FN', '{"ar": "استرداد المصروفات النثرية"}'::jsonb, '{"ar": "مطالبة بمصروفات مدفوعة بالفواتير، ومراجعتها واعتمادها وصرفها على السجل المالي للموظف."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "المالية (FI)"}'::jsonb, 'medium', 'wave2', null, 30, now(), 'system:catalogue-1.0'),
  ('FN-04', 'FN', '{"ar": "البدلات والتعويضات الأخرى"}'::jsonb, '{"ar": "نموذج واحد بأنواع معتمدة: بدل السكن ومطالباته، وبدل التأثيث، وبدل الانتقال، وبدل تعليم اللغة العربية والثقافة الإسلامية، وبدل التأشيرة، وبدل تجديد الإقامة، وبدل نقل الأمناء المساعدين، وبدل حضور اللجان؛ بالتحقق من الاستحقاق والاعتماد والصرف من خلال الرواتب."}'::jsonb, '{"ar": "موظف"}'::jsonb, '{"ar": "الرواتب (PY: أنواع الأجر) والاعتمادات (FM)"}'::jsonb, 'medium', 'wave2', null, 40, now(), 'system:catalogue-1.0'),
